/// <summary>
/// 传递给 ItemSlotView 的纯显示数据 DTO，无行为。
/// Controller 从 ItemManager/ItemData 提取后传入 View。
/// </summary>
public struct ItemViewData : IEquatable<ItemViewData>
{
    public Sprite Icon;
    public string Name;
    public string Description;
    public ItemQuality Quality;
    public int Count;

    public bool Equals(ItemViewData other)
    {
        return ReferenceEquals(Icon, other.Icon)
            && Name == other.Name
            && Description == other.Description
            && Quality == other.Quality
            && Count == other.Count;
    }

    public override bool Equals(object obj)
        => obj is ItemViewData other && Equals(other);

    public override int GetHashCode()
    {
        unchecked
        {
            int hash = 17;
            hash = hash * 23 + (Icon != null ? Icon.GetHashCode() : 0);
            hash = hash * 23 + (Name != null ? Name.GetHashCode() : 0);
            hash = hash * 23 + (Description != null ? Description.GetHashCode() : 0);
            hash = hash * 23 + Quality.GetHashCode();
            hash = hash * 23 + Count.GetHashCode();
            return hash;
        }
    }
}

using UnityEngine;

/// <summary>
/// 属性修改道具效果 — 每次 OnAcquire/OnRemove 直接加减 delta，天然支持叠加。
///
/// 示例:
///   "疾风之靴" — statName="MoveSpeed", flatBonus=2f → 持有3个 = +6速度
///   "力量腰带" — statName="MaxHealth", flatBonus=50f
///   乘算: percentBonus=1.3f → 每次 +30%，OnRemove 时 /1.3 回退
/// </summary>
[CreateAssetMenu(fileName = "StatModifierEffect", menuName = "Game/Item Effect/Stat Modifier")]
public class StatModifierEffect : ItemEffectBase
{
    [Header("属性修改")]
    [Tooltip("属性名: MaxHealth / MoveSpeed / AttackStrength / BulletSpeed / ShotsPerMinute / ColliderRadius")]
    public string statName;

    [Tooltip("固定加成值（加算模式下每次加减此值）")]
    public float flatBonus;

    [Tooltip("百分比缩放: 1.3 = +30%。乘算模式下生效，OnRemove 时 /percentBonus 回退")]
    public float percentBonus = 1f;

    [Tooltip("true=乘算(percentBonus), false=加算(flatBonus)")]
    public bool isMultiplicative = false;

    public override void OnAcquire(GameObject owner)
    {
        var stats = owner.GetComponent<PlayerStats>();
        if (stats == null) return;

        float current = stats.GetStatValue(statName);

        float newValue;
        if (isMultiplicative)
            newValue = current * percentBonus + flatBonus;
        else
            newValue = current + flatBonus;

        stats.SetStatValue(statName, newValue);
    }

    public override void OnRemove(GameObject owner)
    {
        var stats = owner.GetComponent<PlayerStats>();
        if (stats == null) return;

        float current = stats.GetStatValue(statName);

        float newValue;
        if (isMultiplicative)
            newValue = (current - flatBonus) / percentBonus;
        else
            newValue = current - flatBonus;

        stats.SetStatValue(statName, newValue);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 挂载 Buff 道具效果 — 获得道具时给持有者挂载一个 Buff。
/// 每次 OnAcquire 创建新 Buff 实例，支持叠加持有。
/// 移除时销毁最后一个 Buff。
/// </summary>
[CreateAssetMenu(fileName = "ApplyBuffEffect", menuName = "Game/Item Effect/Apply Buff")]
public class ApplyBuffEffect : ItemEffectBase
{
    [Header("Buff 配置")]
    [Tooltip("要挂载的 Buff 数据资产")]
    public BuffData buffData;

    /// <summary>已挂载的 Buff 实例列表（用于逐层移除）</summary>
    private readonly List<BuffInstance> _appliedBuffs = new List<BuffInstance>();

    public override void OnAcquire(GameObject owner)
    {
        if (buffData == null)
        {
            Debug.LogWarning("ApplyBuffEffect: buffData 为空！");
            return;
        }

        var buffManager = owner.GetComponent<BuffManager>();
        if (buffManager == null)
        {
            Debug.LogWarning($"ApplyBuffEffect: owner '{owner.name}' 没有 BuffManager 组件");
            return;
        }

        var instance = buffManager.ApplyBuff(buffData, owner);
        _appliedBuffs.Add(instance);
    }

    public override void OnRemove(GameObject owner)
    {
        if (_appliedBuffs.Count == 0) return;

        var buffManager = owner.GetComponent<BuffManager>();
        if (buffManager == null) return;

        // 移除最后一个（LIFO）
        int lastIndex = _appliedBuffs.Count - 1;
        var instance = _appliedBuffs[lastIndex];
        _appliedBuffs.RemoveAt(lastIndex);

        buffManager.RemoveBuff(instance);
    }
}

using System;
using UnityEngine;

/// <summary>
/// 条件触发道具效果 — 监听指定事件，条件满足时执行子效果。
/// 支持叠加持有：首次获取时订阅事件，最后一次移除时取消订阅。
///
/// 示例:
///   "复仇之盾" — triggerEvent=OnDamaged, executeEffect=AoE伤害效果
///   "不死鸟之羽" — triggerEvent=OnHealthBelow(20%), executeEffect=回满血效果
/// </summary>
[CreateAssetMenu(fileName = "ConditionalEffect", menuName = "Game/Item Effect/Conditional")]
public class ConditionalEffect : ItemEffectBase
{
    [Header("触发条件")]
    [Tooltip("触发事件类型")]
    public ItemTriggerEvent triggerEvent;

    [Header("条件参数")]
    [Tooltip("OnHealthBelow 时的阈值（0-1，如 0.2 = 20%）")]
    [Range(0f, 1f)] public float healthThreshold = 0.2f;

    [Header("执行效果")]
    [Tooltip("条件满足时执行的效果（可嵌套其他 ItemEffectBase）")]
    public ItemEffectBase executeEffect;

    [Header("冷却与次数")]
    [Tooltip("触发冷却（秒），0 = 无冷却")]
    public float cooldown;

    [Tooltip("最大触发次数，0 = 无限")]
    public int maxTriggerCount;

    private float _lastTriggerTime = -999f;
    private int _triggerCount;
    private int _refCount; // 持有层数

    // 缓存的组件引用
    private PlayerStats _stats;
    private PlayerCombat _combat;
    private PlayerSkillManager _skillManager;

    public override void OnAcquire(GameObject owner)
    {
        if (_refCount == 0)
        {
            // 首次获取：缓存引用并订阅事件
            _stats = owner.GetComponent<PlayerStats>();
            _combat = owner.GetComponent<PlayerCombat>();
            _skillManager = owner.GetComponent<PlayerSkillManager>();
            SubscribeEvents();
        }
        _refCount++;
    }

    public override void OnRemove(GameObject owner)
    {
        _refCount--;
        if (_refCount <= 0)
        {
            _refCount = 0;
            UnsubscribeEvents();
            _stats = null;
            _combat = null;
            _skillManager = null;
        }
    }

    private void SubscribeEvents()
    {
        switch (triggerEvent)
        {
            case ItemTriggerEvent.OnDamaged:
                if (_stats != null) _stats.OnHealthChanged += HandleHealthChanged;
                break;
            case ItemTriggerEvent.OnAttack:
                if (_combat != null) _combat.OnShoot += HandleAttack;
                break;
            case ItemTriggerEvent.OnSkillCast:
                if (_skillManager != null) _skillManager.OnSkillCast += HandleSkillCast;
                break;
            case ItemTriggerEvent.OnHealthBelow:
                if (_stats != null) _stats.OnHealthChanged += HandleHealthBelow;
                break;
        }
    }

    private void UnsubscribeEvents()
    {
        if (_stats != null)
        {
            _stats.OnHealthChanged -= HandleHealthChanged;
            _stats.OnHealthChanged -= HandleHealthBelow;
        }
        if (_combat != null)
            _combat.OnShoot -= HandleAttack;
        if (_skillManager != null)
            _skillManager.OnSkillCast -= HandleSkillCast;
    }

    private void TryTrigger(GameObject owner)
    {
        if (cooldown > 0f && Time.time - _lastTriggerTime < cooldown)
            return;
        if (maxTriggerCount > 0 && _triggerCount >= maxTriggerCount)
            return;

        _lastTriggerTime = Time.time;
        _triggerCount++;
        executeEffect?.OnAcquire(owner);
    }

    private void HandleHealthChanged(float current, float max) { }
    private void HandleAttack(Vector2 direction, float bulletSpeed, float attackStrength)
    {
        TryTrigger(_stats?.gameObject);
    }
    private void HandleSkillCast(int slotIndex, SkillData data)
    {
        TryTrigger(_stats?.gameObject);
    }
    private void HandleHealthBelow(float current, float max)
    {
        if (current / max <= healthThreshold)
            TryTrigger(_stats?.gameObject);
    }
}

/// <summary>
/// 道具触发事件类型
/// </summary>
public enum ItemTriggerEvent
{
    OnAttack,
    OnDamaged,
    OnKill,
    OnRoomEnter,
    OnRoomClear,
    OnHealthBelow,
    OnSkillCast,
    OnDodge
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerController : MonoBehaviour
{
    private Rigidbody2D _rb;
    private PlayerCombat _combat;
    private PlayerStats _stats;
    private Vector2 _moveInput;

    /// <summary>攻击输入委托，由 PlayerCombat 订阅</summary>
    public event System.Action OnAttackInput;

    /// <summary>输入是否被锁定 (房间切换期间)</summary>
    public bool InputLocked { get; set; }

    void Awake()
    {
        _rb = GetComponent<Rigidbody2D>();
        _combat = GetComponent<PlayerCombat>();
        _stats = GetComponent<PlayerStats>();

        if (_combat != null)
            OnAttackInput += _combat.TryShoot;

#if UNITY_EDITOR
        if (_rb == null)
            Debug.LogWarning("PlayerController: 未找到 Rigidbody2D 组件！");
        if (_combat == null)
            Debug.LogWarning("PlayerController: 未找到 PlayerCombat 组件！");
        if (_stats == null)
            Debug.LogWarning("PlayerController: 未找到 PlayerStats 组件！");
#endif
    }

    void Start()
    {
        if (_stats == null) return;

        CircleCollider2D circle = GetComponent<CircleCollider2D>();
        if (circle != null)
        {
            _stats.ColliderRadius = circle.radius * Mathf.Max(transform.localScale.x, transform.localScale.y);
        }

        // Start 时 MapManager.Instance 已经初始化 (Awake 时序保证)
        if (MapManager.Instance != null)
        {
            MapManager.Instance.OnRoomSwitchStarted += (f, t) => InputLocked = true;
            MapManager.Instance.OnRoomSwitchCompleted += (t) => InputLocked = false;
        }
    }

    void Update()
    {
        if (_stats != null && _stats.IsDead) return;
        if (InputLocked)
        {
            _moveInput = Vector2.zero;
            return;
        }

        float horizontal = Input.GetAxisRaw("Horizontal");
        float vertical = Input.GetAxisRaw("Vertical");
        _moveInput = new Vector2(horizontal, vertical);
        _moveInput = Vector2.ClampMagnitude(_moveInput, 1f);

        if (Input.GetMouseButton(0))
        {
            OnAttackInput?.Invoke();
        }
    }

    void FixedUpdate()
    {
        if (_rb == null || _stats == null) return;
        if (_stats.IsDead) return;
        if (InputLocked) return;

        // 使用 Rigidbody2D 物理驱动，墙壁碰撞由 Collider2D 处理
        _rb.velocity = _moveInput * _stats.MoveSpeed;
    }
}

using System.Collections;
using System.Collections.Generic;
using UnityEngine;

public class PlayerCombat : MonoBehaviour
{
    [Header("射击配置")]
    [SerializeField] private GameObject bulletPrefab;

    private PlayerStats _stats;
    private float _lastShootTime = -10f;

    /// <summary>射击事件委托：参数为 (方向, 子弹速度, 攻击力)</summary>
    public event System.Action<Vector2, float, float> OnShoot;

    private void Awake()
    {
        _stats = GetComponent<PlayerStats>();

        if (bulletPrefab == null)
        {
#if UNITY_EDITOR
            Debug.LogWarning("PlayerCombat: 未指定子弹预制体！");
#endif
        }
        else
        {
            // 预热对象池，避免首帧给卡
            ProjectilePool.Prewarm(bulletPrefab, 10);
        }
    }

    /// <summary>尝试射击，由 PlayerController 通过委托调用</summary>
    public void TryShoot()
    {
        if (bulletPrefab == null || _stats == null)
            return;

        if (Time.time < _lastShootTime + _stats.ShootCooldown)
            return;

        // 获取鼠标世界位置
        Vector3 mouseWorldPos = Camera.main.ScreenToWorldPoint(Input.mousePosition);
        mouseWorldPos.z = 0f;

        Vector2 direction = (mouseWorldPos - transform.position).normalized;

        float bulletSpeed = _stats.BulletSpeed;
        float attackStrength = _stats.AttackStrength;

        // 从对象池获取子弹
        GameObject bullet = ProjectilePool.Get(bulletPrefab, transform.position, Quaternion.identity);
        Projectile proj = bullet.GetComponent<Projectile>();
        if (proj != null)
        {
            proj.Initialize(direction, bulletSpeed, attackStrength, Projectile.OwnerType.Player, gameObject);
        }
#if UNITY_EDITOR
        else
        {
            Debug.LogWarning("子弹预制体缺少 Projectile 组件！");
        }
#endif

        _lastShootTime = Time.time;

        OnShoot?.Invoke(direction, bulletSpeed, attackStrength);
    }
}

using System.Collections;
using UnityEngine;
using UnityEngine.UI;

/// <summary>
/// 小地图 UI — 在界面右上角显示房间和走廊的关系图。
/// 从 MapManager.RoomGraph 读取数据，绘制到 RawImage 的 Texture2D 上。
/// </summary>
[RequireComponent(typeof(RawImage))]
public class MinimapUI : MonoBehaviour
{
    [Header("小地图尺寸")]
    [SerializeField] private int _textureSize = 256;
    [SerializeField] private float _uiWidth = 200f;
    [SerializeField] private float _uiHeight = 200f;

    [Header("绘制参数")]
    [SerializeField] private int _corridorWidth = 4;
    [SerializeField] [Range(0.2f, 1f)] private float _roomDisplayScale = 0.55f;

    [Header("房间颜色")]
    [SerializeField] private Color _startColor = new(0.3f, 0.8f, 0.3f);
    [SerializeField] private Color _normalColor = new(0.5f, 0.5f, 0.5f);
    [SerializeField] private Color _treasureColor = new(1f, 0.84f, 0f);
    [SerializeField] private Color _bossColor = new(0.8f, 0.2f, 0.2f);
    [SerializeField] private Color _shopColor = new(0.3f, 0.6f, 1f);
    [SerializeField] private Color _exitColor = new(0.6f, 0.2f, 0.8f);
    [SerializeField] private Color _hiddenColor = new(0.85f, 0.5f, 0.1f);
    [SerializeField] private Color _explorableColor = new(0.25f, 0.25f, 0.25f, 0.45f);
    [SerializeField] private Color _explorableBorderColor = new(0.18f, 0.18f, 0.18f, 0.55f);
    [SerializeField] private Color _explorableCorridorColor = new(0.18f, 0.18f, 0.18f, 0.35f);
    [SerializeField] private Color _currentBorderColor = Color.white;
    [SerializeField] private Color _corridorColor = new(0.28f, 0.28f, 0.28f, 0.7f);
    [SerializeField] private Color _bgColor = new(0f, 0f, 0f, 0.6f);

    private RawImage _rawImage;
    private Texture2D _texture;
    private int _currentRoomId = -1;
    private System.Collections.Generic.HashSet<int> _visitedRoomIds = new();

    private void Awake()
    {
        _rawImage = GetComponent<RawImage>();
        if (_rawImage == null)
            _rawImage = gameObject.AddComponent<RawImage>();

        ResizeUI();
        CreateTexture();
    }

    private void Start()
    {
        // 订阅房间切换事件
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchCompleted += OnRoomSwitchCompleted;

        // 尝试立即绘制；如果地图还没生成，延迟一帧再试
        TryDraw();

        if (_currentRoomId < 0)
            StartCoroutine(DelayedDraw());
    }

    private IEnumerator DelayedDraw()
    {
        yield return null;
        TryDraw();
    }

    private void OnDestroy()
    {
        if (MapManager.Instance != null)
            MapManager.Instance.OnRoomSwitchCompleted -= OnRoomSwitchCompleted;

        if (_texture != null)
            Destroy(_texture);
    }

    private void OnRoomSwitchCompleted(int newRoomId)
    {
        _visitedRoomIds.Add(newRoomId);
        _currentRoomId = newRoomId;
        var graph = MapManager.Instance?.RoomGraph;
        if (graph != null)
            DrawMap(graph);
    }

    // ==================== 公开方法 ====================

    [ContextMenu("Refresh")]
    public void Refresh()
    {
        var mgr = MapManager.Instance;
        if (mgr == null) return;
        var graph = mgr.RoomGraph;
        if (graph == null) return;
        _currentRoomId = mgr.CurrentRoomId;
        _visitedRoomIds.Add(_currentRoomId);
        DrawMap(graph);
    }

    // ==================== 内部绘制 ====================

    private void ResizeUI()
    {
        var rt = GetComponent<RectTransform>();
        if (rt == null) rt = gameObject.AddComponent<RectTransform>();
        rt.SetSizeWithCurrentAnchors(RectTransform.Axis.Horizontal, _uiWidth);
        rt.SetSizeWithCurrentAnchors(RectTransform.Axis.Vertical, _uiHeight);
    }

    private void CreateTexture()
    {
        _texture = new Texture2D(_textureSize, _textureSize, TextureFormat.RGBA32, false);
        _texture.filterMode = FilterMode.Point;
        _texture.wrapMode = TextureWrapMode.Clamp;
        _rawImage.texture = _texture;
    }

    private void TryDraw()
    {
        var mgr = MapManager.Instance;
        if (mgr == null) return;
        var graph = mgr.RoomGraph;
        if (graph == null || graph.nodes.Count == 0) return;

        _currentRoomId = mgr.CurrentRoomId;
        _visitedRoomIds.Add(_currentRoomId);
        DrawMap(graph);
    }

    private void DrawMap(RoomGraph graph)
    {
        if (_texture == null) CreateTexture();
        if (graph == null || graph.nodes.Count == 0) return;

        // 1. 计算世界边界
        float minX = float.MaxValue, maxX = float.MinValue;
        float minY = float.MaxValue, maxY = float.MinValue;

        foreach (var node in graph.nodes)
        {
            Vector2 half = node.config.roomSize * 0.5f;
            minX = Mathf.Min(minX, node.worldPosition.x - half.x);
            maxX = Mathf.Max(maxX, node.worldPosition.x + half.x);
            minY = Mathf.Min(minY, node.worldPosition.y - half.y);
            maxY = Mathf.Max(maxY, node.worldPosition.y + half.y);
        }

        float worldW = maxX - minX;
        float worldH = maxY - minY;
        if (worldW < 0.001f || worldH < 0.001f) return;

        // 2. 计算缩放比例 (保持宽高比，并预留边距)
        float texPadding = _textureSize * 0.06f;
        float usableSize = _textureSize - texPadding * 2f;
        float scale = Mathf.Min(usableSize / worldW, usableSize / worldH);
        float offsetX = (usableSize - worldW * scale) / 2f;
        float offsetY = (usableSize - worldH * scale) / 2f;

        // 世界坐标 -> 像素坐标
        int WorldToPixelX(float wx) => Mathf.RoundToInt(texPadding + offsetX + (wx - minX) * scale);
        int WorldToPixelY(float wy) => Mathf.RoundToInt(texPadding + offsetY + (wy - minY) * scale);

        // 3. 清空纹理
        Color[] pixels = new Color[_textureSize * _textureSize];
        for (int i = 0; i < pixels.Length; i++)
            pixels[i] = _bgColor;

        // 4. 计算"可探索"房间: 未访问但与已探索房间相邻的房间 (隐藏房除外)
        var explorableIds = new System.Collections.Generic.HashSet<int>();
        foreach (var node in graph.nodes)
        {
            if (_visitedRoomIds.Contains(node.roomId)) continue;
            if (node.roomType == RoomType.Hidden) continue;
            foreach (var conn in node.connections)
            {
                if (_visitedRoomIds.Contains(conn.Key))
                {
                    explorableIds.Add(node.roomId);
                    break;
                }
            }
        }

        // 5. 画走廊 (隐藏房不参与可探索连线)
        foreach (var node in graph.nodes)
        {
            foreach (var conn in node.connections)
            {
                if (node.roomId >= conn.Key) continue;
                var neighbor = graph.GetNode(conn.Key);
                if (neighbor == null) continue;

                // 隐藏房不显示在可探索状态
                if (!_visitedRoomIds.Contains(node.roomId) && node.roomType == RoomType.Hidden) continue;
                if (!_visitedRoomIds.Contains(neighbor.roomId) && neighbor.roomType == RoomType.Hidden) continue;

                bool aVisited = _visitedRoomIds.Contains(node.roomId);
                bool bVisited = _visitedRoomIds.Contains(neighbor.roomId);
                bool aExplorable = explorableIds.Contains(node.roomId);
                bool bExplorable = explorableIds.Contains(neighbor.roomId);

                bool draw = (aVisited || bVisited) && (aVisited || bVisited || aExplorable || bExplorable);
                if (!draw) continue;

                Color lineColor = (aVisited && bVisited) ? _corridorColor : _explorableCorridorColor;

                Vector2 centerA = node.worldPosition;
                Vector2 centerB = neighbor.worldPosition;
                DrawThickLine(pixels,
                    WorldToPixelX(centerA.x), WorldToPixelY(centerA.y),
                    WorldToPixelX(centerB.x), WorldToPixelY(centerB.y),
                    lineColor, _corridorWidth);
            }
        }

        // 6. 画可探索房间: Boss/Exit 用真实颜色，其余用灰色
        foreach (var node in graph.nodes)
        {
            if (!explorableIds.Contains(node.roomId)) continue;

            bool isBossOrExit = node.roomType == RoomType.Boss || node.roomType == RoomType.Exit;
            Color fillColor = isBossOrExit ? GetRoomColor(node.roomType) : _explorableColor;
            Color borderColor = isBossOrExit
                ? Color.Lerp(GetRoomColor(node.roomType), Color.black, 0.3f)
                : _explorableBorderColor;

            Vector2 half = node.config.roomSize * 0.5f * _roomDisplayScale;
            int px1 = ClampPixel(WorldToPixelX(node.worldPosition.x - half.x));
            int py1 = ClampPixel(WorldToPixelY(node.worldPosition.y - half.y));
            int px2 = ClampPixel(WorldToPixelX(node.worldPosition.x + half.x));
            int py2 = ClampPixel(WorldToPixelY(node.worldPosition.y + half.y));

            for (int y = py1; y <= py2; y++)
            {
                for (int x = px1; x <= px2; x++)
                {
                    bool isBorder = (x == px1 || x == px2 || y == py1 || y == py2);
                    pixels[y * _textureSize + x] = isBorder ? borderColor : fillColor;
                }
            }
        }

        // 7. 画已探索房间
        foreach (var node in graph.nodes)
        {
            if (!_visitedRoomIds.Contains(node.roomId)) continue;

            Color roomColor = GetRoomColor(node.roomType);

            Vector2 half = node.config.roomSize * 0.5f * _roomDisplayScale;
            int px1 = ClampPixel(WorldToPixelX(node.worldPosition.x - half.x));
            int py1 = ClampPixel(WorldToPixelY(node.worldPosition.y - half.y));
            int px2 = ClampPixel(WorldToPixelX(node.worldPosition.x + half.x));
            int py2 = ClampPixel(WorldToPixelY(node.worldPosition.y + half.y));

            for (int y = py1; y <= py2; y++)
            {
                for (int x = px1; x <= px2; x++)
                {
                    bool isBorder = (x == px1 || x == px2 || y == py1 || y == py2);

                    if (isBorder)
                    {
                        pixels[y * _textureSize + x] = Color.Lerp(roomColor, Color.black, 0.3f);
                    }
                    else
                    {
                        pixels[y * _textureSize + x] = roomColor;
                    }
                }
            }

            // 8. 高亮当前房间边框
            if (node.roomId == _currentRoomId)
            {
                for (int y = py1; y <= py2; y++)
                {
                    for (int x = px1; x <= px2; x++)
                    {
                        bool isBorder = (x == px1 || x == px2 || y == py1 || y == py2);
                        if (isBorder)
                            pixels[y * _textureSize + x] = _currentBorderColor;
                    }
                }
            }
        }

        _texture.SetPixels(pixels);
        _texture.Apply();
    }

    private int ClampPixel(int val)
    {
        return Mathf.Clamp(val, 0, _textureSize - 1);
    }

    private void DrawThickLine(Color[] pixels, int x0, int y0, int x1, int y1, Color color, int thickness)
    {
        int dx = Mathf.Abs(x1 - x0);
        int dy = Mathf.Abs(y1 - y0);
        int sx = x0 < x1 ? 1 : -1;
        int sy = y0 < y1 ? 1 : -1;
        int err = dx - dy;
        int half = thickness / 2;

        while (true)
        {
            // 画中心点周围的方形
            for (int dy2 = -half; dy2 <= half; dy2++)
            {
                for (int dx2 = -half; dx2 <= half; dx2++)
                {
                    int tx = x0 + dx2;
                    int ty = y0 + dy2;
                    if (tx >= 0 && tx < _textureSize && ty >= 0 && ty < _textureSize)
                        pixels[ty * _textureSize + tx] = color;
                }
            }

            if (x0 == x1 && y0 == y1) break;

            int e2 = 2 * err;
            if (e2 > -dy) { err -= dy; x0 += sx; }
            if (e2 < dx) { err += dx; y0 += sy; }
        }
    }

    private Color GetRoomColor(RoomType type)
    {
        return type switch
        {
            RoomType.Start => _startColor,
            RoomType.Normal => _normalColor,
            RoomType.Treasure => _treasureColor,
            RoomType.Boss => _bossColor,
            RoomType.Shop => _shopColor,
            RoomType.Exit => _exitColor,
            RoomType.Hidden => _hiddenColor,
            _ => Color.gray
        };
    }
}

using UnityEngine;

/// <summary>
/// 房间门 — 挂载在每个门 GO 上。
/// 普通门：Trigger 检测玩家 → 切换房间。
/// 隐藏墙：清房后 openTrigger 启用但不放行玩家，子弹命中 N 次后墙壁破碎。
/// </summary>
public class RoomPortal : MonoBehaviour
{
    [Header("门配置")]
    public DoorDirection direction;
    public int targetRoomId = -1;

    [Header("组件引用")]
    [Tooltip("门 GO 的 SpriteRenderer")]
    public SpriteRenderer doorSprite;

    [Tooltip("开门/子弹检测的 Trigger Collider")]
    public Collider2D openTrigger;

    [Tooltip("关门/隐藏墙时激活的阻挡物")]
    public GameObject doorBlocker;

    [Header("触发设置")]
    public string targetTag = "Player";

    private bool _locked;
    private bool _isPermanentWall;
    private bool _breakable;
    private int _hiddenWallHP;
    private int _currentHP;

    private void Awake()
    {
        if (doorSprite == null) doorSprite = GetComponent<SpriteRenderer>();
        if (openTrigger == null) openTrigger = GetComponent<Collider2D>();
        if (openTrigger != null) openTrigger.isTrigger = true;
    }

    private void OnTriggerEnter2D(Collider2D other)
    {
        // 可破坏墙壁：检测子弹
        if (_breakable && other.TryGetComponent<Projectile>(out var proj))
        {
            OnBulletHit(proj);
            return;
        }

        // 隐藏墙未破坏前不放行玩家 (_locked 为 true)
        if (_locked) return;

        // 正常的门传送
        if (targetRoomId < 0) return;
        if (!other.CompareTag(targetTag)) return;
        if (MapManager.Instance == null) return;
        if (other.GetComponent<PlayerStats>() == null) return;

        MapManager.Instance.SwitchRoom(targetRoomId, direction);
    }

    private void OnBulletHit(Projectile proj)
    {
        _currentHP--;
        Destroy(proj.gameObject);

        if (_currentHP <= 0)
            BreakWall();
    }

    private void BreakWall()
    {
        _breakable = false;
        _hiddenWallHP = 0;
        SetLocked(false);
        Debug.Log($"RoomPortal: 隐藏墙已破坏 (方向: {direction})");
    }

    /// <summary>设置为隐藏墙</summary>
    public void SetAsBreakableWall(int hp)
    {
        if (hp <= 0) return;
        _hiddenWallHP = hp;
        _currentHP = hp;
        _breakable = false;
        _locked = true;

        if (doorSprite != null) doorSprite.enabled = false;
        if (openTrigger != null) openTrigger.enabled = false;
        if (doorBlocker != null) doorBlocker.SetActive(true);
    }

    /// <summary>激活可破坏状态（清房后调用）：启用 openTrigger 接收子弹</summary>
    public void SetBreakable()
    {
        if (_hiddenWallHP <= 0 || _breakable) return;
        _breakable = true;
        if (openTrigger != null) openTrigger.enabled = true;
        Debug.Log($"RoomPortal: 隐藏墙可破坏 (方向: {direction}, HP: {_currentHP})");
    }

    public bool IsBreakable => _breakable;
    public int HiddenWallHP => _hiddenWallHP;

    /// <summary>锁定/解锁门</summary>
    public void SetLocked(bool locked)
    {
        if (_isPermanentWall) return;
        _locked = locked;

        if (openTrigger != null)
            openTrigger.enabled = !locked;

        if (doorSprite != null)
            doorSprite.enabled = !locked;

        if (doorBlocker != null)
            doorBlocker.SetActive(locked);
    }

    /// <summary>永久隐藏为墙壁（无连接房间）</summary>
    public void HideAsWall()
    {
        targetRoomId = -1;
        _isPermanentWall = true;
        _breakable = false;
        _hiddenWallHP = 0;

        if (openTrigger != null) openTrigger.enabled = false;
        if (doorSprite != null) doorSprite.enabled = false;
        if (doorBlocker != null) doorBlocker.SetActive(true);
    }
}

using System.Collections.Generic;
using UnityEngine;

/// <summary>
/// 房间根节点 — 挂载在每个房间预制体的根 GameObject 上。
/// 管理房间的激活/隐藏、门位置查询、生成点等。
/// </summary>
public class RoomRoot : MonoBehaviour
{
    [Header("房间配置")]
    public RoomConfig config;

    [Header("房间 ID (运行时赋值)")]
    public int roomId;

    [Header("门 Transform (按方向索引: Top=0, Bottom=1, Left=2, Right=3)")]
    public Transform topDoor;
    public Transform bottomDoor;
    public Transform leftDoor;
    public Transform rightDoor;

    [Header("敌人生成点")]
    public Transform[] enemySpawnPoints;

    [Header("道具生成点")]
    public Transform[] itemSpawnPoints;

    [Header("房间边界 (用于摄像机)")]
    public Vector2 roomSize = new Vector2(20f, 12f);

    /// <summary>获取房间中心世界坐标</summary>
    public Vector2 Center => (Vector2)transform.position;

    /// <summary>获取房间边界矩形</summary>
    public Rect Bounds => new(Center - roomSize * 0.5f, roomSize);

    /// <summary>获取指定方向门的世界坐标</summary>
    public Vector3 GetDoorWorldPosition(DoorDirection dir)
    {
        var t = GetDoorTransform(dir);
        return t != null ? t.position : transform.position;
    }

    /// <summary>获取指定方向门的 Transform</summary>
    public Transform GetDoorTransform(DoorDirection dir)
    {
        return dir switch
        {
            DoorDirection.Top => topDoor,
            DoorDirection.Bottom => bottomDoor,
            DoorDirection.Left => leftDoor,
            DoorDirection.Right => rightDoor,
            _ => null
        };
    }

    /// <summary>获取所有可用的门方向</summary>
    public List<DoorDirection> GetAvailableDoors()
    {
        var doors = new List<DoorDirection>();
        if (topDoor != null) doors.Add(DoorDirection.Top);
        if (bottomDoor != null) doors.Add(DoorDirection.Bottom);
        if (leftDoor != null) doors.Add(DoorDirection.Left);
        if (rightDoor != null) doors.Add(DoorDirection.Right);
        return doors;
    }

    private List<GameObject> _childrenCache = new();

    /// <summary>激活房间 (显示所有子物体)</summary>
    public void Activate()
    {
        gameObject.SetActive(true);
    }

    /// <summary>隐藏房间</summary>
    public void Deactivate()
    {
        gameObject.SetActive(false);
    }

    private void OnDrawGizmosSelected()
    {
        Gizmos.color = Color.green;
        Gizmos.DrawWireCube(Center, roomSize);

        if (config != null)
        {
            var dirs = new[] { DoorDirection.Top, DoorDirection.Bottom, DoorDirection.Left, DoorDirection.Right };
            foreach (var dir in dirs)
            {
                if (config.HasDoor(dir))
                {
                    Gizmos.color = Color.yellow;
                    Gizmos.DrawSphere(GetDoorWorldPosition(dir), 0.3f);
                }
            }
        }
    }
}

using System.Collections;
using UnityEngine;

/// <summary>
/// 房间摄像机控制器 — 固定房间视角 + 房间切换平滑滑动。
/// 挂载在 MainCamera 上。
/// 
/// 行为:
/// - 在房间中: 摄像机固定在房间中心，orthographicSize = 根据房间大小自动计算
/// - 房间切换: 平滑滑动到新房间中心 (0.5s)
/// - 过渡期间通知 MapManager 锁定玩家输入
/// </summary>
[RequireComponent(typeof(Camera))]
public class RoomCameraController : MonoBehaviour
{
    [Header("过渡设置")]
    [Tooltip("房间切换过渡时长 (秒)")]
    public float transitionDuration = 0.5f;

    [Tooltip("过渡曲线")]
    public AnimationCurve transitionCurve = AnimationCurve.EaseInOut(0f, 0f, 1f, 1f);

    [Header("视角设置")]
    [Tooltip("摄像机 Orthographic Size 与房间高度的比例 (1.0 = 正好包住房间内高，1.2 = 含墙壁+门边距)")]
    public float sizeScale = 1.2f;

    [Tooltip("最小 Orthographic Size")]
    public float minOrthoSize = 5f;

    [Tooltip("最大 Orthographic Size")]
    public float maxOrthoSize = 25f;

    private Camera _cam;
    private Vector3 _targetPosition;
    private float _targetOrthoSize;
    private bool _isTransitioning;
    private Coroutine _transitionCoroutine;
    private RoomRoot _currentRoom;

    private void Awake()
    {
        _cam = GetComponent<Camera>();
        _targetPosition = transform.position;
        _targetOrthoSize = _cam.orthographicSize;
    }

    private void LateUpdate()
    {
        if (!_isTransitioning)
        {
            // 固定模式：直接锁定在目标位置
            transform.position = _targetPosition;
            _cam.orthographicSize = _targetOrthoSize;
        }
    }

    /// <summary>切换摄像机到目标房间</summary>
    /// <param name="room">目标房间</param>
    /// <param name="onComplete">过渡完成回调</param>
    public void MoveToRoom(RoomRoot room, System.Action onComplete = null)
    {
        if (room == null) return;

        _currentRoom = room;
        Vector3 roomCenter = room.Center;
        roomCenter.z = transform.position.z; // 保持 Z 轴

        // 计算合适的 Orthographic Size
        float targetSize = CalculateOrthoSize(room);

        if (transitionDuration <= 0f || _targetPosition == roomCenter)
        {
            // 瞬间切换
            _targetPosition = roomCenter;
            _targetOrthoSize = targetSize;
            onComplete?.Invoke();
            return;
        }

        // 平滑过渡
        if (_transitionCoroutine != null)
            StopCoroutine(_transitionCoroutine);
        _transitionCoroutine = StartCoroutine(TransitionRoutine(roomCenter, targetSize, onComplete));
    }

    /// <summary>根据房间大小计算合适的 Orthographic Size。</summary>
    /// <remarks>房间视觉范围 = roomSize + 四周墙壁(0.5×2=1)。取高宽中较严的方向，确保全覆盖。</remarks>
    private float CalculateOrthoSize(RoomRoot room)
    {
        // 含墙壁的完整视觉尺寸
        float visualW = room.roomSize.x + 1f;
        float visualH = room.roomSize.y + 1f;

        // Orthographic Size = half height → 纵向覆盖需要 visualH/2
        float sizeFromHeight = visualH * 0.5f * sizeScale;
        // 横向覆盖需要 visualW/2 / aspect
        float sizeFromWidth = visualW * 0.5f * sizeScale / _cam.aspect;
        float size = Mathf.Max(sizeFromHeight, sizeFromWidth);
        return Mathf.Clamp(size, minOrthoSize, maxOrthoSize);
    }

    /// <summary>平滑过渡协程</summary>
    private IEnumerator TransitionRoutine(Vector3 targetPos, float targetSize, System.Action onComplete)
    {
        _isTransitioning = true;

        Vector3 startPos = transform.position;
        float startSize = _cam.orthographicSize;

        float elapsed = 0f;

        while (elapsed < transitionDuration)
        {
            elapsed += Time.deltaTime;
            float t = Mathf.Clamp01(elapsed / transitionDuration);
            float curveT = transitionCurve.Evaluate(t);

            transform.position = Vector3.Lerp(startPos, targetPos, curveT);
            _cam.orthographicSize = Mathf.Lerp(startSize, targetSize, curveT);

            yield return null;
        }

        // 最终值精确设置
        transform.position = targetPos;
        _cam.orthographicSize = targetSize;
        _targetPosition = targetPos;
        _targetOrthoSize = targetSize;

        _isTransitioning = false;
        onComplete?.Invoke();
    }

    /// <summary>立即跳转到房间 (无过渡)</summary>
    public void SnapToRoom(RoomRoot room)
    {
        if (room == null) return;

        _currentRoom = room;
        Vector3 roomCenter = room.Center;
        roomCenter.z = transform.position.z;

        transform.position = roomCenter;
        _targetPosition = roomCenter;
        _targetOrthoSize = CalculateOrthoSize(room);
        _cam.orthographicSize = _targetOrthoSize;
    }

    public RoomRoot CurrentRoom => _currentRoom;
    public bool IsTransitioning => _isTransitioning;
}

